"""Build a separate non-production dev mod around an existing generated live unit."""
from __future__ import annotations
import argparse,json,shutil,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path[:0]=[str(ROOT),str(ROOT/"src"),str(ROOT/"third_party/python-deps")]
sys.stdout.reconfigure(encoding="utf-8",errors="replace")
from aoe2_genie_tooling import GenieWorkspace
from aoe2.dat_integration import (allocation_key,apply_generated_corpse_contract,category_stem,clone_graphic,
                                  resolve_corpse_allocation,sha256,validate_generated_corpse_contract)
from aoe2.scenario_validation import validate_scenario

def main():
 p=argparse.ArgumentParser();p.add_argument("--manifest-hash",required=True);p.add_argument("--unit-name",required=True);p.add_argument("--base-mod",type=Path,required=True);p.add_argument("--base-scenario",type=Path,required=True);p.add_argument("--corpse-sld-report",type=Path,required=True);p.add_argument("--profile",type=Path,default=ROOT/"config/aoe2/integration_profiles/infantry_melee_fast_generated_corpse_v1.json");p.add_argument("--registry",type=Path,default=ROOT/"config/aoe2/integration_allocations.json");a=p.parse_args()
 profile=json.loads(a.profile.read_text());registry=json.loads(a.registry.read_text());namespace=profile["allocation_namespace"];key=allocation_key(a.manifest_hash,namespace);base_allocation={"key":key,**registry["allocations"][key]};sld=json.loads(a.corpse_sld_report.read_text())
 if sld.get("render_mode")!="fast" or sld.get("release_eligible") is not False:raise RuntimeError("corpse dev integration requires FAST non-release SLD evidence")
 identity=sld["corpse"]["sha256"][:16];root=ROOT/"build/dev-test/rome2aoe2"/a.unit_name.casefold()/a.manifest_hash[:16]/"fast-corpse"/identity;mod=root/f"Rome2AoE2 {a.unit_name} FAST Corpse Test";scenario=root/f"Rome2AoE2{a.unit_name.replace('_','')}FASTCorpseTest.aoe2scenario"
 if mod.exists():raise FileExistsError(f"refusing to overwrite existing dev test: {mod}")
 shutil.copytree(a.base_mod,mod);shutil.copy2(a.base_scenario,scenario);base_mod_info=json.loads((a.base_mod/"info.json").read_text());dat_path=mod/"resources/_common/dat/empires2_x2_p1.dat";workspace=GenieWorkspace.load(dat_path);allocation=resolve_corpse_allocation(workspace,registry,base_allocation)
 live=workspace.unit_manager.get(allocation["unit_id"]);corpse=workspace.unit_manager.clone_into(allocation["corpse_unit_id"],profile["corpse_template_unit_id"],name=f"{a.unit_name} generated corpse",on_conflict="error",fill_gaps="placeholder");reference=workspace.dat.sprites[profile["expected_template_corpse_graphic_id"]];frames=int(sld["corpse"]["frames_per_direction"]);fps=float(sld["corpse_fps"]);stem=category_stem(a.unit_name,"corpse");graphic=clone_graphic(workspace,reference,allocation["corpse_graphic_id"],stem,f"{a.unit_name} generated corpse",frames,fps);mapping=apply_generated_corpse_contract(live,corpse,graphic.id);audit=validate_generated_corpse_contract(live,corpse,graphic.id,(profile["expected_template_corpse_graphic_id"],))
 graphics=mod/"resources/_common/drs/graphics";death_source=Path(sld["death"]["path"]);corpse_source=Path(sld["corpse"]["path"]);death_dest=graphics/f"{category_stem(a.unit_name,'death')}_x2.sld";corpse_dest=graphics/f"{stem}_x2.sld";shutil.copy2(death_source,death_dest);shutil.copy2(corpse_source,corpse_dest);workspace.save(dat_path)
 written=GenieWorkspace.load(dat_path);written_live=written.unit_manager.get(allocation["unit_id"]);written_corpse=written.unit_manager.get(allocation["corpse_unit_id"]);roundtrip=validate_generated_corpse_contract(written_live,written_corpse,allocation["corpse_graphic_id"],(profile["expected_template_corpse_graphic_id"],));scenario_validation=validate_scenario(scenario,written,(allocation["unit_id"],));source_scenario_sha=sha256(a.base_scenario)
 if scenario_validation["sha256"]!=source_scenario_sha:raise RuntimeError("reused scenario is not byte-identical to known-good source")
 info={"Author":"Rome2AoE2","CacheStatus":0,"Title":f"Rome2AoE2 {a.unit_name} FAST Corpse Test","Description":"TEST / NON-PRODUCTION generated corpse decay; not release eligible."};(mod/"info.json").write_text(json.dumps(info,indent=2)+"\n")
 receipt={"format":"rome2aoe2.fast-corpse-dev-integration","version":2,"release_eligible":False,"manifest_hash":a.manifest_hash,"profile":profile,"allocation":allocation,"mapping":mapping,"corpse_visual_contract":audit,"roundtrip_visual_contract":roundtrip,"dat":{"path":str(dat_path),"sha256":sha256(dat_path)},"mod":str(mod),"mod_title":info["Title"],"conflicting_mod_titles":[base_mod_info["Title"]],"scenario":str(scenario),"scenario_sha256":sha256(scenario),"scenario_reuse":{"source":str(a.base_scenario),"source_sha256":source_scenario_sha,"byte_identical":True},"scenario_validation":scenario_validation,"assets":[{"path":str(death_dest),"sha256":sha256(death_dest)},{"path":str(corpse_dest),"sha256":sha256(corpse_dest)}],"validation":{"dead_unit_remapped":written_live.dead_unit_id==allocation["corpse_unit_id"],"dead_unit_not_152":written_live.dead_unit_id!=profile["corpse_template_unit_id"],"militia_corpse_graphic_unreachable":profile["expected_template_corpse_graphic_id"] not in set(roundtrip["reachable"].values()),"source_composition_preserved":True,"installed_mod_is_separate":True}}
 path=root/"fast-corpse-integration-receipt.json";path.write_text(json.dumps(receipt,indent=2,sort_keys=True)+"\n");print(path)
if __name__=="__main__":main()
